#define NLATEX (sizeof(latex_tab) / sizeof(latex_tab[0]))
#define MAXNAME 25

static int cmp_name (const void * a, const void * b)
{
	return strcmp(((const LatexSym *) a)->name, ((const LatexSym *) b)->name);
}

static int is_letter (char c)
{
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

/* the character of the longest name at s (after the backslash) and the
   length of that name, or NULL. A name that ends with a letter must not be
   followed by one: \alphax stays as it is. */
const char * latex_symbol (const char * s, int * len)
{
	char buf[MAXNAME + 1];
	int n;
	for (n = 0; n < MAXNAME && s[n] && s[n] != ' ' && s[n] != '\t' && s[n] != '\n'; n++)
		buf[n] = s[n];
	for ( ; n > 0; n--)
		{
		LatexSym key, * r;
		buf[n] = 0;
		if (is_letter(buf[n - 1]) && is_letter(s[n])) continue;
		key.name = buf;
		r = (LatexSym *) bsearch(& key, latex_tab, NLATEX, sizeof(LatexSym), cmp_name);
		if (r)
			{
			* len = n;
			return r->utf8;
			}
		}
	return NULL;
}

/* the ASCII character of a superscript at s (² -> '2', ⁻ -> '-'), its
   length in *len; 0 if there is none */
static char superscript (const unsigned char * s, int * len)
{
	if (s[0] == 0xC2 && (s[1] == 0xB2 || s[1] == 0xB3 || s[1] == 0xB9))
		{ * len = 2; return s[1] == 0xB2 ? '2' : s[1] == 0xB3 ? '3' : '1'; }
	if (s[0] == 0xE2 && s[1] == 0x81 && (s[2] == 0xB0 || (s[2] >= 0xB4 && s[2] <= 0xB9) || s[2] == 0xBB))
		{ * len = 3; return s[2] == 0xBB ? '-' : s[2] == 0xB0 ? '0' : '0' + s[2] - 0xB0; }
	return 0;
}

/* 2026: superscripts (the output of PRETTY 1) as powers, outside of strings:
   x² -> x^(2), x⁻¹ -> x^(-1). A copy, or NULL if there is none. */
static char * superscript_convert (const char * line)
{
	const unsigned char * p;
	char * out, * q;
	int len, quote = 0, any = 0;
	for (p = (const unsigned char *) line; * p && ! any; p++)
		if (* p == '"') quote = ! quote;
		else if (! quote && superscript(p, & len)) any = 1;
	if (! any) return NULL;
	out = (char *) malloc(3 * strlen(line) + 1);
	if (! out) return NULL;
	quote = 0;
	for (p = (const unsigned char *) line, q = out; * p; )
		{
		if (* p == '"') quote = ! quote;
		if (! quote && superscript(p, & len))
			{
			* q++ = '^'; * q++ = '(';
			while (superscript(p, & len)) { * q++ = superscript(p, & len); p += len; }
			* q++ = ')';
			}
		else
			* q++ = (char) * p++;
		}
	* q = 0;
	return out;
}

static char * names_convert (const char * line);

/* a copy of the line with the names replaced (\alpha -> α) and the
   superscripts as powers (x² -> x^(2)); NULL if there is none. The caller
   frees it. */
char * latex_convert (const char * line)
{
	char * a = names_convert(line), * b = superscript_convert(a ? a : line);
	if (! b) return a;
	free(a);
	return b;
}

static char * names_convert (const char * line)
{
	const char * p, * u;
	char * out, * q;
	int len, any = 0;
	for (p = strchr(line, '\\'); p; p = strchr(p + 1, '\\'))
		if (latex_symbol(p + 1, & len)) { any = 1; break; }
	if (! any) return NULL;
	out = (char *) malloc(4 * strlen(line) + 1);	/* a name is not shorter than its character */
	if (! out) return NULL;
	for (p = line, q = out; * p; )
		if (* p == '\\' && (u = latex_symbol(p + 1, & len)) != NULL)
			{
			strcpy(q, u);
			q += strlen(u);
			p += len + 1;
			}
		else
			* q++ = * p++;
	* q = 0;
	return out;
}
